add_action( 'admin_init', 'perfectpixel_id_column_setup' );

function perfectpixel_id_column_setup() {
	foreach ( get_post_types( array( 'show_ui' => true ) ) as $type ) {
		add_filter( "manage_{$type}_posts_columns", 'perfectpixel_id_column' );
		add_action( "manage_{$type}_posts_custom_column", 'perfectpixel_id_column_value', 10, 2 );
	}
	add_filter( 'manage_media_columns', 'perfectpixel_id_column' );
	add_action( 'manage_media_custom_column', 'perfectpixel_id_column_value', 10, 2 );
	add_filter( 'manage_users_columns', 'perfectpixel_id_column' );
	add_filter( 'manage_users_custom_column', 'perfectpixel_id_column_user_value', 10, 3 );
	foreach ( get_taxonomies( array( 'show_ui' => true ) ) as $taxonomy ) {
		add_filter( "manage_edit-{$taxonomy}_columns", 'perfectpixel_id_column' );
		add_filter( "manage_{$taxonomy}_custom_column", 'perfectpixel_id_column_term_value', 10, 3 );
	}
	add_action( 'admin_head', 'perfectpixel_id_column_css' );
}

function perfectpixel_id_column( $columns ) {
	$columns['perfectpixel_id'] = 'ID';
	return $columns;
}

function perfectpixel_id_column_value( $column, $id ) {
	if ( 'perfectpixel_id' === $column ) {
		echo (int) $id;
	}
}

function perfectpixel_id_column_user_value( $output, $column, $user_id ) {
	return 'perfectpixel_id' === $column ? (string) (int) $user_id : $output;
}

function perfectpixel_id_column_term_value( $output, $column, $term_id ) {
	return 'perfectpixel_id' === $column ? (string) (int) $term_id : $output;
}

function perfectpixel_id_column_css() {
	echo '<style>.column-perfectpixel_id{width:60px}</style>';
}
